// Hold the run for a human if the total looks wrong: above an absolute
// ceiling, or more than N times last month. Nothing is transferred either way.
const cfg = $('Config').first().json.config;
const MULTIPLIER = Number(cfg.payout_sanity_multiplier);
const CEILING_CENTS = Number(cfg.payout_ceiling_cents);

const rows = $input.all().map((i) => i.json).filter((r) => r.amount_cents !== undefined);
const total = rows.reduce((s, r) => s + Number(r.amount_cents), 0);
const prevTotal = Number($('Previous period total').first().json.total_cents ?? 0);

const reasons = [];
if (total > CEILING_CENTS) reasons.push(`total ${total} cents is above the ceiling ${CEILING_CENTS}`);
if (prevTotal > 0 && total > prevTotal * MULTIPLIER) reasons.push(`total ${total} cents is more than ${MULTIPLIER}x last period's ${prevTotal}`);

return [{ json: {
  ...$('Period').first().json,
  creators: rows.length,
  total_cents: total,
  previous_total_cents: prevTotal,
  sane: reasons.length === 0,
  reason: reasons.join('; ') || 'within expected bounds',
} }];

